def transform(grid):
    g=[row[:] for row in grid]
    n=len(g); m=len(g[0])
    bars=[]
    for r,row in enumerate(g):
        vals=[v for v in row if v]
        if len(vals)>=3 and len(set(vals))==1:
            bars.append((r, vals[0], {c for c,v in enumerate(row) if v==vals[0]}))
    cols={c for r in range(n-3,n) for c,v in enumerate(g[r]) if v}
    for c in cols:
        hits=[(r,color) for r,color,filled in bars if c not in filled and 0<c<m-1 and g[r][c]==0 and g[r][c-1]==color and g[r][c+1]==color and any(g[rr][c] for rr in range(r+1,n))]
        prev=-1
        for r,color in hits:
            for y in range(prev+1,r+1):
                if g[y][c]==0: g[y][c]=color
            prev=r
    return g
